patch:
diff --git a/repro-emfile/check.js b/repro-emfile/check.js
new file mode 100644
index 0000000..dadb650
--- /dev/null
+++ b/repro-emfile/check.js
@@ -0,0 +1,78 @@
+#!/usr/bin/env node
+/**
+ * Check: `eslint . --fix` must fix every auto-fixable file, even when thousands of
+ * files have fixes and the process has a limited number of file descriptors.
+ *
+ * Exits 0 if `eslint . --fix` exits 0 and every file was fixed.
+ * Exits 1 otherwise (prints what happened).
+ *
+ * Linux/macOS only (uses `ulimit -n` to cap open file descriptors).
+ * Run from the repo root:  node repro-emfile/check.js
+ *
+ * Env overrides: FILES (default 3000), FD_LIMIT (default 1024, the usual Linux soft limit).
+ */
+"use strict";
+
+const fs = require("node:fs");
+const os = require("node:os");
+const path = require("node:path");
+const { spawnSync } = require("node:child_process");
+
+const FILES = Number(process.env.FILES || 3000);
+const FD_LIMIT = Number(process.env.FD_LIMIT || 1024);
+const eslintBin = path.resolve(__dirname, "..", "bin", "eslint.js");
+
+const dir = fs.mkdtempSync(path.join(os.tmpdir(), "eslint-emfile-"));
+
+try {
+	// Flat config with one auto-fixable rule; `let x = N;` -> `const x = N;`
+	fs.writeFileSync(
+		path.join(dir, "eslint.config.js"),
+		'module.exports = [{ rules: { "prefer-const": "error" } }];\n',
+	);
+	fs.mkdirSync(path.join(dir, "src"));
+	for (let i = 0; i < FILES; i++) {
+		fs.writeFileSync(
+			path.join(dir, "src", `f${i}.js`),
+			`let x = ${i};\nconsole.log(x);\n`,
+		);
+	}
+
+	// Same as the report: `eslint ./ --fix`, run with a capped fd limit.
+	const res = spawnSync(
+		"/bin/sh",
+		[
+			"-c",
+			'ulimit -n "$1" && exec "$2" "$3" ./ --fix',
+			"sh",
+			String(FD_LIMIT),
+			process.execPath,
+			eslintBin,
+		],
+		{ cwd: dir, encoding: "utf8" },
+	);
+
+	let unfixed = 0;
+	for (let i = 0; i < FILES; i++) {
+		const text = fs.readFileSync(path.join(dir, "src", `f${i}.js`), "utf8");
+		if (!text.startsWith("const x")) {
+			unfixed++;
+		}
+	}
+
+	console.log(`files=${FILES} fd_limit=${FD_LIMIT} eslint_exit=${res.status}`);
+	console.log(`files still unfixed after --fix: ${unfixed}/${FILES}`);
+
+	if (res.status !== 0 || unfixed !== 0) {
+		console.log("--- eslint output ---");
+		console.log((res.stdout || "") + (res.stderr || ""));
+		console.log(
+			"FAIL: expected eslint --fix to exit 0 and fix all files",
+		);
+		process.exitCode = 1;
+	} else {
+		console.log("PASS: all files fixed, exit 0");
+	}
+} finally {
+	fs.rmSync(dir, { recursive: true, force: true });
+}
